model.actualStatus := THIS^.actualStatus;
model.actual := THIS^.actual;
model.average := THIS^.average;
model.stat := THIS^.stat;

stat.enabled := F_EnabledStatus(
    superState := TRUE,
    isEnabled := config_ref.enabled);
proc.reset();

model.setPoint := THIS^.setPoint;
model.zoneTemp := THIS^.zoneTemp;
model.actualStatus := THIS^.actualStatus;
model.power := THIS^.power;
model.active := THIS^.active;
model.deviation := THIS^.deviation;
model.isControlled := THIS^.isControlled;
model.stat := THIS^.stat;
THIS^.proc.reset._copyToModel_Process( model := model.proc.reset );

proc.warm_up( isEnabled := stat.state = TempControlStatus.idle );
proc.stop( isEnabled := (stat.state = TempControlStatus.warming_up) OR (stat.state = TempControlStatus.controlling) );
proc.reset();

THIS^.proc.warm_up._copyFromModel_Process( model := model.proc.warm_up );
THIS^.proc.stop._copyFromModel_Process( model := model.proc.stop );
THIS^.proc.reset._copyFromModel_Process( model := model.proc.reset );

model.tempMeasurements := THIS^.tempMeasurements;
