model.avgTemperature := THIS^.avgTemperature;
model.maxTemperatureDeviation := THIS^.maxTemperatureDeviation;
model.isControlled := THIS^.isControlled;
model.setPointRamped := THIS^.setPointRamped;
model.heaters := THIS^.heaters;
model.badHealthSensors := THIS^.badHealthSensors;
model.badHealthHeaters := THIS^.badHealthHeaters;
model.stat := THIS^.stat;
THIS^.proc.warm_up._copyToModel_Process( model := model.proc.warm_up );
THIS^.proc.stop._copyToModel_Process( model := model.proc.stop );
THIS^.proc.reset._copyToModel_Process( model := model.proc.reset );

parts.VesselTempControl(
    activity_ref := activity_ref,
    services_ref := services_ref,
    config_ref := config.vesselTempControl);
parts.configManager();
stat.health := F_HealthStatus(
    superState := TRUE,
    isGood := parts.VesselTempControl.stat.health = HealthStatus.good,
    hasWarning := parts.VesselTempControl.stat.health = HealthStatus.warning);
proc.initialize();

THIS^.parts.VesselTempControl._copyFromModel_TempControl( model := model.parts.VesselTempControl );
THIS^.parts.configManager._copyFromModel_ConfigManager( model := model.parts.configManager );
THIS^.proc.initialize._copyFromModel_Process( model := model.proc.initialize );

